<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { api, ApiError } from '../api'
import type { Product } from '../types'
import { formatDate, productTitle, statusLabels, toast } from '../utils'
import AttributeEditor from '../components/AttributeEditor.vue'
import AttachmentList from '../components/AttachmentList.vue'
import LinkManager from '../components/LinkManager.vue'
import RevisionPanel from '../components/RevisionPanel.vue'
import ConflictDialog from '../components/ConflictDialog.vue'
import { useEvents } from '../events'
const route = useRoute(); const router = useRouter(); const id = route.params.id as string; const product = ref<Product>(); const loading = ref(true); const saving = ref(false); const error = ref(''); const dirty = ref(false); const savedPayload = ref(''); const showHistory = ref(false); const uploadBusy = ref(false); const conflict = ref<{ current: Product; submitted: Record<string, unknown> } | null>(null); const remoteNotice = ref(false)
const payload = computed(() => product.value ? { version: product.value.version, chinese_name: product.value.chinese_name, english_name: product.value.english_name, company: product.value.company, category: product.value.category, description: product.value.description, development_status: product.value.development_status, attributes: product.value.attributes.map(({ key,value,certainty }) => ({ key,value,certainty })) } : null)
const payloadKey = (value: Record<string, unknown> | null) => JSON.stringify(Object.fromEntries(Object.entries(value || {}).filter(([key]) => key !== 'version')))
watch(payload, value => { dirty.value = payloadKey(value) !== savedPayload.value }, { deep: true })
function apply(value: Product) { product.value = value; savedPayload.value = payloadKey(payload.value); dirty.value = false; remoteNotice.value = false }
async function load(force = false) { loading.value = true; try { const latest = await api<Product>(`/products/${id}`); if (product.value && dirty.value && !force) remoteNotice.value = true; else apply(latest) } catch (e) { error.value = (e as Error).message } finally { loading.value = false } }
async function save() { if (!payload.value) return; saving.value = true; error.value = ''; try { apply(await api<Product>(`/products/${id}`, { method: 'PATCH', body: JSON.stringify(payload.value) })); toast('已保存') } catch (e) { if (e instanceof ApiError && e.status === 409 && e.details?.current) conflict.value = { current: e.details.current, submitted: { ...payload.value, ...e.details.submitted } }; else error.value = (e as Error).message } finally { saving.value = false } }
function useServer() { if (conflict.value) apply(conflict.value.current); conflict.value = null }
async function mergeLatest() { if (!product.value || !conflict.value) return; product.value.version = conflict.value.current.version; conflict.value = null; await save() }
async function upload(images: File[]) { uploadBusy.value = true; try { for (const file of images) { const form = new FormData(); form.append('product_id', id); form.append('file', file); product.value?.attachments.push(await api<any>('/attachments', { method: 'POST', body: form })) } } catch (e) { error.value = (e as Error).message } finally { uploadBusy.value = false } }
async function deleteAttachment(attachmentID: string) { if (!confirm('删除这张图片？')) return; await api(`/attachments/${attachmentID}`, { method: 'DELETE' }); if (product.value) product.value.attachments = product.value.attachments.filter(item => item.id !== attachmentID) }
async function refreshLinks() { const latest = await api<Product>(`/products/${id}`); if (product.value && dirty.value) { product.value.links = latest.links; product.value.idea_count = latest.idea_count } else apply(latest) }
async function remove() { if (!product.value || !confirm('将这个商品移入回收站？关联灵感不会被删除。')) return; await api(`/products/${id}`, { method: 'DELETE', body: JSON.stringify({ version: product.value.version }) }); router.push('/products') }
onMounted(() => load()); useEvents(() => { if (dirty.value) remoteNotice.value = true; else load() })
</script>
<template><div v-if="loading" class="muted">读取中…</div><p v-else-if="!product" class="error-text">{{ error }}</p><template v-else><div class="page-heading"><div><RouterLink to="/products">← 返回商品库</RouterLink><h1>{{ productTitle(product) }}</h1><p>创建于 {{ formatDate(product.created_at) }} · 版本 {{ product.version }}</p></div><div class="heading-actions"><button class="secondary" @click="showHistory = !showHistory">修改历史</button><button class="danger-button" @click="remove">移入回收站</button></div></div><p v-if="remoteNotice" class="ai-status">服务器上有新变更，保存时会进行版本检查。</p><div class="detail-layout"><div class="detail-main"><section class="panel"><h2>当前商品设定</h2><div class="field-inline"><div class="field"><label>商品中文名</label><input v-model="product.chinese_name" maxlength="160" placeholder="可留空" /></div><div class="field"><label>商品英文名</label><input v-model="product.english_name" maxlength="160" placeholder="可留空" /></div></div><div class="field-inline"><div class="field"><label>所属公司</label><input v-model="product.company" maxlength="160" placeholder="可留空" /></div><div class="field"><label>商品分类</label><input v-model="product.category" maxlength="100" placeholder="可留空" /></div></div><div class="field"><label>制作状态</label><select v-model="product.development_status"><option v-for="key in ['concept','design','production','completed']" :key="key" :value="key">{{ statusLabels[key] }}</option></select></div><div class="field"><label>商品描述</label><textarea v-model="product.description" rows="8" placeholder="游戏效果、包装和其他设定可直接写在这里，或在下方添加动态属性。"></textarea></div><div class="field"><span class="field-label">动态属性</span><AttributeEditor v-model="product.attributes" /></div><p v-if="error" class="error-text">{{ error }}</p><div class="form-actions"><button class="primary" :disabled="saving || !dirty" @click="save">{{ saving ? '保存中…' : dirty ? '保存修改' : '已保存' }}</button><span v-if="dirty" class="muted">有未保存修改</span></div></section><section class="panel"><h2>商品图片与包装</h2><AttachmentList :items="product.attachments" :busy="uploadBusy" @upload="upload" @delete="deleteAttachment" /></section><RevisionPanel v-if="showHistory" kind="product" :id="id" :version="product.version" @restored="load(true)" /></div><aside class="side-panel"><section class="panel"><h2>关联灵感</h2><LinkManager owner-type="product" :owner-id="id" :links="product.links || []" @changed="refreshLinks" /></section></aside></div></template><ConflictDialog v-if="conflict" :current="conflict.current" :submitted="conflict.submitted" @server="useServer" @merge="mergeLatest" @cancel="conflict = null" /></template>
